/* Resource outcomes stay separate from happiness scale definitions and feeling outcomes. */
(function(root){
'use strict';
const R=root.ResourceCalibration,W=root.WamDecisionLearning,$=id=>document.getElementById(id),contexts={everyday:'Tasks / class / rest',purchase:'Purchases',relationship:'Relationships',income:'Income decisions'};
let enabled=true,data=[],cache=new Map();try{enabled=JSON.parse(localStorage.getItem('worth-resource-learning-v1')||'{}').enabled!==false;}catch{}
const box=document.createElement('section');box.id='resourceLearning';box.innerHTML='<h3>Learn the time and effort it really takes</h3><p>Record actual activity time, recovery time and workload for the option you chose. Time and effort are learned separately from feelings; no happiness anchors are required for resource learning.</p><label><input id="useResourceLearning" type="checkbox" style="width:auto"> Use checked time and effort estimates in future scores</label><p id="resourceLearningStatus" role="status"></p><div id="resourceLearningEvidence" class="math-table"></div><details><summary>Resource formulas, units and checks</summary><p>Time: learned duration = max(0, exp(log(1 + forecast) + β₀ + β₁ × log(1 + forecast)/5) − 1). Activity and recovery time are fitted separately. The log transform keeps estimates nonnegative. Effort: learned rating = clip(forecast + β₀ + β₁ × centered forecast, scale minimum, scale maximum). Coefficients use the same ridge update (XᵀX + 5I)⁻¹Xᵀ(actual − forecast), on log time for durations and the original rating scale for effort.</p><p>Each decision type, resource and unit has its own history. Ordinary decisions use minutes and the existing 1–5 overall-effort scale. Income comparisons use weekly work/commute hours, recovery hours and 0–10 intensity. Weekly effort load is then recomputed as learned work hours × learned intensity / 10. These scales describe your own workload, not calories or biological energy.</p><p>At least 10 comparable outcomes and four chronological checks are required, with six earlier outcomes available at each checked forecast. Average absolute error must improve by more than 1 minute, 0.1 weekly hours, or 0.05 effort-rating points, as applicable. These are app settings. Time estimates beyond a factor of two of the observed (1 + forecast) range and effort forecasts more than one point outside the observed range stay unchanged. Histories use at most 200 outcomes each.</p><p>Only the chosen option supplies actual data. A changed choice requires new measurements; an unchosen option is never treated as observed. Original forecasts and saved scores are preserved. Hard-limit values stay fixed and are checked against the learned estimates; the score may warn that a plan now exceeds them. Estimates can still be wrong. Both weekly time components fall back to the entered forecasts if their learned sum would exceed 168 hours.</p></details>';
$('decisionLearning').querySelector('details').before(box);$('useResourceLearning').checked=enabled;
function add(parent,tag,value){const node=document.createElement(tag);node.textContent=value;parent.append(node);return node;}
function rebuild(){data=R.observations(saved);cache=new Map();draw();}
function model(context,mode,dimension){const key=JSON.stringify([context,mode,dimension]);if(!cache.has(key))cache.set(key,R.train(data.filter(r=>r.context===context&&r.mode===mode&&r.dimension===dimension),R.config(mode,dimension)));return cache.get(key);}
function draw(){const out=$('resourceLearningEvidence');out.replaceChildren();$('resourceLearningStatus').textContent=`${data.length} usable resource measurements from ${new Set(data.map(r=>r.id.replace(/:(duration|recovery|effort)$/,''))).size} decisions. `+(enabled?'Checked corrections are enabled.':'Resource learning is off; entered estimates are used.');if(!data.length){add(out,'p','Save a decision, then record its actual time, recovery or effort in Your reflections. Leave unknown measurements blank.');return;}const groups=new Map();data.forEach(r=>groups.set(JSON.stringify([r.context,r.mode,r.dimension]),r));const table=document.createElement('table'),header=document.createElement('tr');for(const h of ['Type / resource','Measurements','Checks','Average error · original → learned','Status'])add(header,'th',h);table.append(header);for(const r of groups.values()){const m=model(r.context,r.mode,r.dimension),tr=document.createElement('tr');for(const value of [contexts[r.context]+' · '+r.dimension,m.n,m.checked,m.mae===null?'Not enough checks':m.originalMae.toFixed(2)+' → '+m.mae.toFixed(2)+' '+m.config.unit,m.ready?'Correction available':m.reason])add(tr,'td',String(value));table.append(tr);}out.append(table);}
function applyResources(raw,context){const models=Object.fromEntries(['duration','recovery','effort'].map(d=>[d,model(context,raw.mode,d)]));return R.apply(raw,models,enabled);}
function combine(result,resource,income=false){const labels={duration:income?'Work + commute':'Activity time',recovery:'Recovery time',effort:income?'Work intensity':'Overall effort'};for(const c of resource.changes)result.snapshot.changes.push({...c,kind:'resource',label:(c.side==='a'?'Main option':'Alternative')+' · '+labels[c.dimension]});result.snapshot.resourceVersion=R.VERSION;result.snapshot.resourceEnabled=enabled;result.snapshot.applied=result.snapshot.applied||resource.applied;result.summary+=' Resource learning: '+(resource.applied?'checked time and/or effort corrections were applied.':!enabled?'switched off; original resource forecasts are used.':'original resource forecasts are used until a correction qualifies.');return result;}
const feelingDecision=W.processDecision;W.processDecision=function(input){const raw={version:R.VERSION,mode:'decision',a:{duration:Number($('minutes').value),recovery:Number($('recovery').value||0),effort:Number($('energy').value)},b:{duration:Number($('altMinutes').value||0),recovery:Number($('altRecovery').value||0),effort:Number($('altEffort').value)}};current.resourceForecasts=raw;const result=feelingDecision(input),resource=applyResources(raw,$('decisionType').value);for(const side of ['a','b']){result.input.factors.time[side]=resource.learned[side].duration+resource.learned[side].recovery;result.input.factors.energy[side]=resource.learned[side].effort;}return combine(result,resource);};
const feelingIncome=W.processIncome;W.processIncome=function(profile,schedule){const result=feelingIncome(profile),raw={version:R.VERSION,mode:'income',a:{duration:schedule.hoursB,recovery:schedule.recoveryB,effort:schedule.effortB},b:{duration:schedule.hoursA,recovery:schedule.recoveryA,effort:schedule.effortA}},resource=applyResources(raw,'income');result.schedule={...schedule,hoursA:resource.learned.b.duration,recoveryA:resource.learned.b.recovery,effortA:resource.learned.b.effort,hoursB:resource.learned.a.duration,recoveryB:resource.learned.a.recovery,effortB:resource.learned.a.effort};return combine(result,resource,true);};
$('useResourceLearning').onchange=()=>{enabled=$('useResourceLearning').checked;try{localStorage.setItem('worth-resource-learning-v1',JSON.stringify({enabled}));}catch{}draw();W.refreshComparisons();};
function decorate(){const items=saved.slice().reverse();Array.from($('entries').children).forEach((row,i)=>{const item=items[i],details=row.querySelector('details'),raw=R.forecasts(item);if(!item||!details||!raw||details.querySelector('.resource-followup'))return;const income=raw.mode==='income',area=document.createElement('fieldset');area.className='resource-followup';add(area,'legend','Actual time, recovery and effort');let choice=row.querySelector('select[aria-label^="Chosen option for "]');if(!choice){choice=document.createElement('select');choice.setAttribute('aria-label','Chosen option for '+item.task);[['','Choose an option…'],['do',item.task],['alt',item.alt]].forEach(([v,t])=>choice.add(new Option(t,v)));choice.value=item.outcomeChoice||item.resourceOutcomes?.choice||item.actualChoice||'';add(area,'label','Which option did you actually choose?');area.append(choice);}const previous=item.resourceOutcomes,fields={};for(const d of ['duration','recovery','effort']){const c=R.config(raw.mode,d),field=document.createElement('input');field.type='number';field.min=c.min;field.max=c.max;field.step=d==='effort'?'.5':income?'.1':'1';field.setAttribute('aria-label','Actual '+d+' for '+item.task);field.value=previous?.choice===choice.value?previous[d]?.value??'':'';const label=d==='duration'?(income?'Actual work + commute':'Actual activity / commute time'):d==='recovery'?'Actual additional recovery time':'Actual '+(income?'work intensity':'overall effort');add(area,'label',label+' · '+c.unit);area.append(field);fields[d]=field;}const confirm=document.createElement('input');confirm.type='checkbox';confirm.style.width='auto';confirm.setAttribute('aria-label','Confirm resource measurements for '+item.task);const label=add(area,'label','');label.append(confirm,document.createTextNode(' These measurements describe the chosen option in the period shown. Recovery excludes activity/work time. Leave unknown values blank.'));const save=document.createElement('button');save.type='button';save.className='quiet';save.textContent='Save actual time & effort';area.append(save);const status=add(area,'p','');status.className='helper';status.setAttribute('role','status');choice.addEventListener('change',()=>{const recorded=item.outcomeChoice||item.resourceOutcomes?.choice||item.feelingOutcomes?.choice||item.actualChoice;if(recorded&&choice.value!==recorded){for(const f of Object.values(fields))f.value='';status.textContent='Choice changed. Enter resource measurements for this option.';}confirm.checked=false;});
 save.onclick=()=>{if(!choice.value||!confirm.checked){status.textContent='Choose an option and confirm the units and measurement period.';return;}if(Object.values(fields).some(f=>!f.checkValidity())||!Object.values(fields).some(f=>f.value!=='')){status.textContent='Enter at least one valid resource measurement.';return;}if(income&&fields.duration.value!==''&&fields.recovery.value!==''&&Number(fields.duration.value)+Number(fields.recovery.value)>168){status.textContent='Work/commute and recovery together cannot exceed 168 hours/week.';return;}const old=item.resourceOutcomes,oldChoice=item.outcomeChoice,oldActual=item.actualChoice,next={choice:choice.value},now=new Date().toISOString();for(const d of ['duration','recovery','effort'])if(fields[d].value!==''){const value=Number(fields[d].value),before=old?.choice===choice.value?old[d]:null;next[d]=before?.value===value&&before.confirmed===true&&Date.parse(before.recordedAt)>Date.parse(item.date)?before:{value,recordedAt:now,confirmed:true};}item.resourceOutcomes=next;item.outcomeChoice=choice.value;item.actualChoice=choice.value;if(!persist()){item.resourceOutcomes=old;item.outcomeChoice=oldChoice;item.actualChoice=oldActual;status.textContent='Could not save resource measurements.';return;}status.textContent='Actual resources saved. Future comparisons use the updated accuracy checks.';rebuild();W.outcomesChanged();};details.append(area);});}
const beforeDecorate=W.decorateFollowups;W.decorateFollowups=function(){beforeDecorate();decorate();rebuild();};
document.addEventListener('wam:outcomes-updated',rebuild);document.addEventListener('wam:history-restored',()=>{rebuild();W.refreshComparisons();});
W.decorateFollowups();
})(typeof globalThis!=='undefined'?globalThis:this);
